operation.add:
// Save design upload data to session
if (isset($this->request->post['design_upload_code']) && $this->request->post['design_upload_code']) {
  $this->session->data['design_uploads'][$this->request->post['product_id']] = array(
    'design_code' => $this->request->post['design_upload_code'],
    'observations' => isset($this->request->post['design_observations']) ? $this->request->post['design_observations'] : ''
  );
}

public function saveDesignUpload($order_id, $product_id, $design_code, $observations) {
  $this->db->query("INSERT INTO " . DB_PREFIX . "order_design_upload SET order_id = '" . (int)$order_id . "', product_id = '" . (int)$product_id . "', design_code = '" . $this->db->escape($design_code) . "', observations = '" . $this->db->escape($observations) . "', date_added = NOW()");
}
